/* asmcapa.h -- normally auto-generated by Allegro's own fix.sh/asmdef.sh
 * build step, detecting which x86 asm-optimized capabilities (e.g. MMX) the
 * host assembler/CPU combination supports. This build defines
 * ALLEGRO_NO_ASM/ALLEGRO_USE_C throughout (see libs/allegro-4.0.2/
 * CMakeLists.txt) and never assembles or generates x86 machine code at all,
 * so no capability is ever asserted here -- this is the correct, empty
 * "nothing detected" case, not a placeholder awaiting real detection.
 */
#ifndef ALLEGRO_ASMCAPA_MINGW32_H
#define ALLEGRO_ASMCAPA_MINGW32_H
#endif
